window.RP_SESSION={"id":"S-7e8e4ac5628f","messages":[{"id":"Plane-0003347","time":"2026-09-26T11:47:00+09:00","room":"Plane","name":"헥터","profile":"헥터","identity":"unresolved","type":"dialogue","body":"슈우욱--\n훈련장에서는 바람을 가르는 소리가 한참 들려옵니다.\n탁-\n그리고 묵직하게 부딪치는 소리도 말이죠.\n그는 자세를 잡고 창을 허수아비를 향해 던지고 뽑아서 다시 자리를 잡아 던지고를 반복합니다.\n.\n그렇게 허수아비가 해집어지고 창끝이 닳도록 연습하고선.\n허수아비를 고치기 위해 헛간에서 짚을 챙겨 왔습니다.\n짚을 엮고 허수아비에 묶어 보강합니다.\n.\n그리고 나서는 창끝의 날을 세우기 위해 대장간으로 향합니다.\n전문적이지는 못하지만 날을 세우고 나간 이를 다듬는것정도는 할아버지를 통해 어린시절에 보고 또 삼촌과 아버지에게 약간 배웠기에 홀로 물을 적시고 날을 갈아봅니다.\n.\n.\n인고의 시간이 지나고 나름 괜찮아졌군요. 기름칠을 좀 해주고서는 가죽으로 창끝을 묶어 가져갑니다.\n.\n창을 두고 와서는 강가에서 몸을 씻어냅니다.\n그 후 몸을 말리고서는 책을 빌려와 모닥불로 향하여..\n- 말을 움직이는 수싸움 -\n이라는 보드게임 내지 말을 움직여 하는 전장을 배껴낸 게임을 공부하는군요.","characters":[]},{"id":"Plane-0003348","time":"2026-09-26T11:47:00+09:00","room":"Plane","name":"헥터","profile":"헥터","identity":"unresolved","type":"dialogue","body":"-fin","characters":[]}]};
